// The few System.Windows.Forms ResX members that dnSpy's project exporter (dnSpy.Decompiler/MSBuild/
// ResXResourceFileWriter.cs) uses: header constants, the schema, and the reader/writer/ResXNullRef type names it
// writes into each .resx. Windows Forms itself does not exist on Linux, and the exporter never reads or writes
// resources through these types, so this assembly carries the names and constants only.
//
// The assembly is named System.Windows.Forms, version 4.0.0.0, public-signed with the ECMA key (token
// b77a5c561934e089), so the type names it yields are exactly the ones Visual Studio and dnSpy write.

namespace System.Resources;

public sealed class ResXResourceWriter
{
